+    /// @param _gameId The ID of the game to cancel
+    function cancelGame(uint256 _gameId) external nonReentrant {
+        Game storage g = games[_gameId];
+
+        if (g.status != GameStatus.WAITING) revert GameNotJoinable();
+        if (msg.sender != g.player1) revert NotGameCreator();
+
+        uint256 stake = g.stake;
+        delete games[_gameId]; // Effects first
+
+        pendingWithdrawals[msg.sender] += stake;
